import {move} from './core.mjs';
export const RELEASE='1.0.0-beta.1p';
export const canonicalCode=value=>String(value??'').normalize('NFKC').trim().toLowerCase();
const number=(v,label)=>{if(!Number.isSafeInteger(v)||v<0)throw Error(label+': usa un entero no negativo.');return v};
const string=(v,label,max=160)=>{if(typeof v!=='string'||v.length>max)throw Error(label+': texto no válido.');return v.trim()};
export function validateInventory(input){
if(!input||input.version!==1||!Array.isArray(input.products)||!Array.isArray(input.events)||input.products.length>10000||input.events.length>100000)throw Error('El archivo no tiene un formato de inventario compatible.');
const ids=new Set(),codes=new Set();const products=input.products.map((p,i)=>{if(!p||typeof p!=='object')throw Error('Producto '+(i+1)+' inválido.');const id=string(p.id,'Identificador',100),code=string(p.code,'Código'),name=string(p.name,'Nombre');if(!id||!code||!name||ids.has(id)||codes.has(canonicalCode(code)))throw Error('Hay productos sin identificar o con códigos duplicados.');ids.add(id);codes.add(canonicalCode(code));const next={id,code,name,qty:number(p.qty,'Cantidad'),min:number(p.min,'Mínimo')};for(const field of ['brand','spec','shelf','level','box'])next[field]=p[field]==null?'':string(p[field],field);if(p.target!=null)next.target=number(p.target,'Stock deseado');if(p.photo){if(typeof p.photo!=='string'||p.photo.length>1800000||!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/]+=*$/.test(p.photo))throw Error('La foto de '+name+' no tiene un formato compatible.');next.photo=p.photo}if(p.emoji)next.emoji=string(p.emoji,'Icono',20);return next});
const eventIds=new Set();const events=input.events.map(e=>{if(!e||typeof e!=='object')throw Error('Historial inválido.');const id=string(e.id,'Identificador de movimiento',100);if(!id||eventIds.has(id)||!Number.isFinite(Date.parse(e.at)))throw Error('Hay movimientos inválidos o repetidos.');eventIds.add(id);const next={id,productId:string(e.productId,'Producto',100),name:string(e.name,'Nombre'),type:string(e.type,'Tipo',30),before:number(e.before,'Cantidad anterior'),after:number(e.after,'Cantidad posterior'),note:string(e.note??'','Nota',500),at:new Date(e.at).toISOString(),device:string(e.device??'importado','Dispositivo',100),sync:'local'};next.delta=next.after-next.before;if(e.actor)next.actor=string(e.actor,'Responsable',60);if(e.requestId)next.requestId=string(e.requestId,'Solicitud',100);return next});
return {version:1,products,events,emptyStartApplied:true,revision:Number.isSafeInteger(input.revision)&&input.revision>=0?input.revision:0,...(Number.isFinite(Date.parse(input.modifiedAt))?{modifiedAt:new Date(input.modifiedAt).toISOString()}:{})};
}
export function readBackup(text,mode){if(typeof text!=='string'||text.length>16000000)throw Error('La copia supera el límite de 16 MB.');let data;try{data=JSON.parse(text)}catch{throw Error('El archivo no es una copia JSON válida.')}if(!['test','real'].includes(data.environment))throw Error('La copia no identifica si pertenece a pruebas o al inventario real.');if(data.environment!==mode)throw Error('Esta copia pertenece a '+(data.environment==='real'?'inventario real':'pruebas')+'. Cambia al mismo inventario antes de restaurarla.');return {data:validateInventory(data),exportedAt:data.exportedAt||'',environment:data.environment}}
export function backupText(db,environment,device){return JSON.stringify({...db,environment,device,appVersion:RELEASE,exportedAt:new Date().toISOString()},null,2)}
export function restock(products){return products.filter(p=>p.qty<=p.min).map(p=>({...p,target:p.target>p.min?p.target:Math.max(p.min+1,p.min*2),buy:Math.max(0,(p.target>p.min?p.target:Math.max(p.min+1,p.min*2))-p.qty)})).sort((a,b)=>a.qty-b.qty||a.name.localeCompare(b.name,'es'))}
export function shoppingCSV(products){const cell=value=>{let s=String(value??'');if(/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};return '\ufeff'+[['Código','Producto','Marca','Disponible','Mínimo','Objetivo','Comprar','Ubicación'],...restock(products).map(p=>[p.code,p.name,p.brand,p.qty,p.min,p.target,p.buy,[p.shelf,p.level,p.box].filter(Boolean).join(' / ')])].map(row=>row.map(cell).join(',')).join('\r\n')}
export function sharedSnapshot(db,mode){return {version:1,environment:mode,revision:db.revision||0,at:new Date().toISOString(),products:db.products.slice(0,3000).map(({id,code,name,brand,spec,shelf,level,box,qty,min,target})=>({id,code,name,brand,spec,shelf,level,box,qty,min,target})),total:db.products.length}}
export function applySharedMove(db,mode,request,device){if(!request||request.environment!==mode)throw Error('El inventario activo cambió en la pantalla principal. Actualiza antes de continuar.');const requestId=string(request.requestId,'Solicitud',100);if(!requestId)throw Error('Solicitud sin identificar.');if(db.events.some(e=>e.requestId===requestId))return false;const p=db.products.find(p=>canonicalCode(p.code)===canonicalCode(request.code));if(!p)throw Error('El producto ya no está disponible. Actualiza el catálogo.');if(request.type==='count'&&request.expectedQty!==p.qty)throw Error('La cantidad cambió desde tu última consulta. Actualiza y vuelve a contar.');const actor=string(request.actor||'Teléfono vinculado','Responsable',60),note=string(request.note||'','Nota',180);move(db,p.id,request.type,request.amount,note,device);db.events[0].actor=actor;db.events[0].requestId=requestId;return true}
